#!/usr/bin/env python3
"""Check the adopted P16 marker, complete generated bytes and pinned baseline.

This is an integrity check, not producer completeness, Lean elaboration or
semantic adequacy. The frozen base commit must exist in the object database.
"""
import os
from pathlib import Path
import subprocess
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]


def main():
    if len(sys.argv) != 1:
        raise SystemExit("usage: check.py")
    environment = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    environment.update(PYTHONDONTWRITEBYTECODE="1", GIT_CONFIG_NOSYSTEM="1",
                       GIT_CONFIG_GLOBAL="/dev/null", GIT_TERMINAL_PROMPT="0",
                       GIT_NO_REPLACE_OBJECTS="1",
                       GIT_CONFIG_COUNT="1", GIT_CONFIG_KEY_0="safe.directory",
                       GIT_CONFIG_VALUE_0=str(ROOT))
    checks = [("generated", "generate.py", ["--migration", "--check"]),
              ("census", "census.py", []),
              ("pinned baseline", "census.py", ["--baseline"])]
    for label, script, arguments in checks:
        print("P16 check: " + label, flush=True)
        result = subprocess.run([sys.executable, "-B", str(HERE / script), *arguments],
                                cwd=ROOT, env=environment)
        if result.returncode:
            return result.returncode
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
